let state;try{state={...JSON.parse(JSON.stringify(defaults)),...JSON.parse(localStorage.getItem('home-v1')||'{}')}}catch{state=JSON.parse(JSON.stringify(defaults))};let tab='Overview',room='All',busy=false,timer=null,backend=false;
