function save(){delete state.chat;delete state.memory;delete state.speak;try{localStorage.setItem('home-v1',JSON.stringify(state))}catch{}}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',2200)}
