let pageMotion=null, motionOrigin=null;
function navigate(t){if(dashboardEditing){dashboardEditing=false;}let previous=tab;let view=$('#view');if(pageMotion){pageMotion.cancel();pageMotion=null}let origin=motionOrigin;motionOrigin=null;tab=t;if(t==='Calendar')selectedDay=dayKey();if(t==='Overview')nightDismissed=periodNow();render();view.scrollTop=0;window.scrollTo(0,0);if(previous===t||matchMedia('(prefers-reduced-motion: reduce)').matches||!view.animate)return;let box=view.getBoundingClientRect();let x=origin?Math.max(0,Math.min(box.width,origin.x-box.left)):box.width/2;let y=origin?Math.max(0,Math.min(box.height,origin.y-box.top)):0;let back=t==='Overview';if(back){let card=view.querySelector('[data-widget="'+previous+'"]');if(card){let r=card.getBoundingClientRect();x=r.left+r.width/2-box.left;y=r.top+r.height/2-box.top}}pageMotion=view.animate([{opacity:.35,transform:`translateY(${back?'-5px':'12px'}) scale(${phoneFace()?(back?.99:.98):(back?.94:.90)})`,transformOrigin:`${x}px ${y}px`},{opacity:1,transform:'translateY(-2px) scale(1.008)',transformOrigin:`${x}px ${y}px`,offset:.78},{opacity:1,transform:'translateY(0) scale(1)',transformOrigin:`${x}px ${y}px`}],{duration:phoneFace()?260:480,easing:'cubic-bezier(.22,.8,.25,1)'});let current=pageMotion;current.onfinish=()=>{if(pageMotion===current)pageMotion=null};}
function clock(){let d=new Date();let hero=$('#heroClock');if(hero&&!document.hidden&&!document.body.classList.contains('clock-mode'))hero.textContent=d.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}).replace(/\s*(AM|PM)$/i,'');$('#clock').textContent=d.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'});$('#date').textContent=d.toLocaleDateString([], {weekday:'long',month:'long',day:'numeric'})}clock();setInterval(clock,1000);
function sceneCards(){return `<div class="scenes">${Object.entries(scenes).map(([n,s])=>`<button class="scene ${n===(typeof lightScene098!=='undefined'?lightScene098:state.scene)?'active':''}" data-scene="${n}" aria-pressed="${n===(typeof lightScene098!=='undefined'?lightScene098:state.scene)}">${icon(s.i)}${n}</button>`).join('')}</div>`}
function tile(i,label,value,detail,go){return `<button class="tile" style="text-align:left;color:inherit" data-tab="${go}"><div class="tiletop">${icon(i)}<span class="muted">↗</span></div><div class="big">${value}</div><h3>${label}</h3><div class="muted">${detail}</div></button>`}
