function media(){return `${streamingLinks()}<div class="panel section"><div class="tvscreen ${state.tv?'':'off'}"><div>${icon('tv',!state.tv)}<div><strong>${state.tv?'HOME TV':'Standby'}</strong></div><div class="muted">Virtual 55-inch display</div></div></div><div class="between"><div><h2 style="margin:0">Entertainment</h2><div class="muted">Hisense · future Google TV integration</div></div><button class="power ${state.tv?'on':''}" data-action="tv" aria-label="Toggle TV" aria-pressed="${state.tv}">${icon('power')}</button></div><section class="section"><div class="between"><h3>Surround sound</h3><span id="vol">${state.volume}%</span></div><input type="range" min="0" max="100" value="${state.volume}" data-volume aria-label="Virtual audio volume"></section><button class="primary" data-scene="Cinema">Activate cinema mode</button></div><p class="note">This is a simulated remote. Streaming apps, volume and television power will require compatible hardware integrations.</p>`}
function settings(){return `<div class="panel"><h2>System</h2><div class="setting between"><div><h3>Device adapter</h3><div class="muted">Simulation · real integration not configured</div></div><span class="tag">Local</span></div><div class="setting between"><div><h3>Reset HOME</h3><div class="muted">Remove local data and return to defaults</div></div><button class="secondary" data-action="reset">Reset</button></div></div>`}
function render(){document.body.dataset.page=tab.toLowerCase();$('.wordmark button').setAttribute('aria-label',tab==='Overview'?'Home':'Back to Home');$('#heading').textContent=({Overview:'Home',Calendar:'Calendar',Tasks:'Tasks',Focus:'Focus',Goals:'Goals',Lighting:'Lighting',Media:'Entertainment',Weather:'Weather',Insights:'Insights',Habits:'Habits',Today:'Today',Settings:'Settings'})[tab];$('#nav').innerHTML=navOrder.map(n=>[n,navs[n]]).map(([n,i])=>`<button class="navbtn ${n===tab?'active':''}" data-tab="${n}" aria-label="${n}" ${n===tab?'aria-current="page"':''}>${icon(i)}<span>${n==='Overview'?'Home':n==='Media'?'Music & TV':n}</span></button>`).join('')+`<button class="navbtn more086 ${!['Overview','Calendar','Tasks','Focus'].includes(tab)?'active':''}" data-more086 aria-label="More pages" aria-haspopup="dialog">${icon('more086')}<span>More</span></button>`;$('#view').innerHTML=({Overview:todayView,Calendar:calendarView,Tasks:tasksView,Focus:focusView,Goals:goalsView,Lighting:lighting,Media:media,Weather:()=>weatherPanel(true),Insights:insights090,Habits:habits090,Today:today092,Settings:settingsV3})[tab]();applyDashboard082();applyDockVisibility()}
