const freshPlan=()=>({events:[],tasks:[],logs:[],focus:{minutes:25,remaining:1500,end:0,label:'Study'},goals:[]});
let plan;try{plan={...freshPlan(),...JSON.parse(localStorage.getItem('home-plan-v3')||'{}')}}catch{plan=freshPlan()}
