const dayKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const asDate=k=>new Date(k+'T12:00:00');const shift=(k,n)=>{let d=asDate(k);d.setDate(d.getDate()+n);return dayKey(d)};const pretty=k=>asDate(k).toLocaleDateString([], {weekday:'short',month:'short',day:'numeric'});const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
let selectedDay=dayKey(),calMode='Month',taskFilter='Open';
function eventsOn(k){return plan.events.filter(e=>matchesRepeat090(e.date,k,e.repeat,e.repeatUntil,e)).map(e=>({...e,date:k})).sort((a,b)=>(a.time||'').localeCompare(b.time||''))}function fmtTime(t){if(!t)return 'All day';let [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`}
function head(i,t,button=''){return `<div class="cardhead">${icon(i)}<h2>${t}</h2>${button}</div>`}function link(t,label){return `<button class="textbutton" data-tab="${t}">${label} ›</button>`}function addBtn(kind,label='Add'){return `<button class="secondary" data-new="${kind}">${icon('plus')} ${label}</button>`}
function eventRows(es,editable=false){return es.length?es.map(e=>`<div class="event"><div class="eventbar" style="background:${eventColors[e.color]||eventColors.Blue}"></div><div class="eventbody"><small>${esc(fmtTime(e.time))}${e.end?' – '+esc(fmtTime(e.end)):''}</small><strong>${esc(e.title)}</strong>${e.notes?`<small>${esc(e.notes)}</small>`:''}${e.repeat&&e.repeat!=='None'?`<small>↻ ${esc(e.repeat)}</small>`:''}${e.blockTask?'<small>Time block</small>':''}</div>${editable?`<button class="tiny" data-edit="event:${esc(e.id)}" data-occurrence091="${esc(e.date)}" aria-label="Edit event">${icon('edit')}</button>`:''}</div>`).join(''):'<p class="empty">Nothing scheduled. Your day is yours to plan.</p>'}
function taskRows(ts,editable=false){ts=ts.filter(t=>!t.habit).sort((a,b)=>priority090(a)-priority090(b)||(a.due||'9999').localeCompare(b.due||'9999'));return ts.length?ts.map(t=>`<div data-task-row092="${esc(t.id)}" class="taskrow ${t.done?'done':''}"><input type="checkbox" data-task="${esc(t.id)}" ${t.done?'checked':''} aria-label="Complete ${esc(t.title)}"><span>${esc(t.title)}${t.priority&&t.priority!=='Normal'?` <span class="priority090 ${t.priority==='High'?'high090':''}">${esc(t.priority)}</span>`:''}${t.repeat&&t.repeat!=='None'?` <small class="muted">↻ ${esc(t.repeat)}</small>`:''}${t.due?`<small class="muted" style="display:block">${esc(pretty(t.due))}</small>`:''}</span>${editable?`<button class="tiny" data-block090="${esc(t.id)}" aria-label="Schedule task">${icon('calendar')}</button><button class="tiny" data-edit="task:${esc(t.id)}" data-occurrence091="${esc(t.occurrence091||dayKey())}" aria-label="Edit task">${icon('edit')}</button>`:''}</div>`).join(''):'<p class="empty">Nothing here yet.</p>'}
function focusRemaining(){return plan.focus.end?Math.max(0,Math.ceil((plan.focus.end-Date.now())/1000)):plan.focus.remaining}function countdown(){let v=focusRemaining();return `${String(Math.floor(v/60)).padStart(2,'0')}:${String(v%60).padStart(2,'0')}`}
function focusCard(){let progress=Math.max(0,Math.min(100,focusRemaining()/(plan.focus.minutes*60)*100));return `<div class="focus-ring" id="focusRing" style="--progress:${progress}%"><div class="focus-inner"><div class="focusface" id="focusClock">${countdown()}</div><p class="muted">${esc(plan.focus.label)}</p></div></div><div class="focusactions"><button class="circle-action" data-focus="reset" aria-label="Reset timer">${icon('reset')}</button><button class="play-action" data-focus="${plan.focus.end?'pause':'start'}" aria-label="${plan.focus.end?'Pause':'Start'} timer">${icon(plan.focus.end?'pause':'play')}</button><button class="circle-action" data-tab="Focus" aria-label="Focus settings">${icon('settings')}</button></div>`}
function roomCards(){return `<div class="roomcards">${[{n:'Bedroom',i:'bed',r:'Bedroom'},{n:'Bathroom',i:'bath',r:'Bathroom'},{n:'Closet',i:'closet',r:'Closet'},{n:'Entertainment',i:'tv',}].map(x=>`<button class="roomcard" ${x.r?`data-roomgo="${x.r}"`:'data-tab="Media"'}>${icon(x.i)}<div><strong>${x.n}</strong><small>${x.r?state.lights.filter(l=>l.room===x.r&&l.on).length+' lights on':state.tv?'Playing · simulated':'Standby'}</small></div></button>`).join('')}</div>`}
function originalTodayView(){let now=new Date(),hour=now.getHours(),done=plan.tasks.filter(t=>t.done).length,all=plan.tasks.length;return `<p class="greeting">Good ${hour<12?'morning':hour<18?'afternoon':'evening'}. Make space for what matters.</p><div class="dashgrid"><section class="glass">${head('calendar','Schedule',link('Calendar','Calendar'))}${eventRows(eventsOn(dayKey()).slice(0,4))}<button class="textbutton" data-new="event">${icon('plus')} New event</button></section><section class="glass">${head('tasks','Reminders',link('Tasks','All tasks'))}<div class="muted">${done} of ${all} completed</div><div class="progress"><span style="width:${all?done/all*100:0}%"></span></div>${taskRows(plan.tasks.filter(t=>!t.done).slice(0,3))}<button class="textbutton" data-new="task">${icon('plus')} New task</button></section><section class="glass">${head('timer','Focus',link('Focus','Session'))}${focusCard()}</section><section class="glass">${head('music','Music',link('Media','Media'))}${musicCard()}</section></div><section class="section"><div class="between sectionhead"><h2>Your space</h2><span class="tag">Simulation</span></div>${roomCards()}</section><section class="section"><div class="between sectionhead"><h2>Scenes</h2>${link('Lighting','Lighting')}</div>${sceneCards()}</section>`}
function calendarView(){let d=asDate(selectedDay),start=dayKey(new Date(d.getFullYear(),d.getMonth(),1)),offset=asDate(start).getDay(),weekStart=shift(selectedDay,-d.getDay()),base=calMode==='Month'?shift(start,-offset):weekStart,n=calMode==='Month'?42:7;let cells=Array.from({length:n},(_,i)=>{let k=shift(base,i),dt=asDate(k),es=eventsOn(k);return `<button class="daycell ${k===selectedDay?'selected':''} ${k===dayKey()?'today':''} ${calMode==='Month'&&dt.getMonth()!==d.getMonth()?'other':''}" data-day="${k}" aria-label="${pretty(k)}"><span class="daynum">${dt.getDate()}</span>${es.slice(0,calMode==='Month'?2:5).map(e=>`<span class="eventchip" style="border-left:3px solid ${eventColors[e.color]||eventColors.Blue}">${esc(e.title)}</span>`).join('')}${es.length>(calMode==='Month'?2:5)?'<span class="subtle">More</span>':''}</button>`}).join('');return `<div class="calendarbar"><div class="row"><button class="tiny" data-calnav="-1" aria-label="Previous">${icon('left')}</button><h2>${calMode==='Month'?d.toLocaleDateString([],{month:'long',year:'numeric'}):pretty(selectedDay)}</h2><button class="tiny" data-calnav="1" aria-label="Next">${icon('right')}</button><button class="textbutton" data-calnav="today">Today</button></div><div class="tabs">${['Day','Week','Month'].map(m=>`<button class="pill ${calMode===m?'active':''}" data-calmode="${m}">${m}</button>`).join('')}</div>${addBtn('event','Event')}</div>${calMode!=='Day'?`<div class="glass"><div class="monthgrid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="weekday">${x}</div>`).join('')}</div><div class="${calMode==='Month'?'monthgrid':'weekgrid'}">${cells}</div></div>`:''}<section class="section glass">${head('calendar',pretty(selectedDay),`<button class="textbutton" data-new="event">+ Add</button>`)}${eventRows(eventsOn(selectedDay),true)}</section><p class="note">HOME calendar is stored on this device. Export events to an .ics file in Settings to import into Apple Calendar; native two-way integration is not connected yet.</p>`}
function tasksView(){let tasks=visibleTasks090();let done=tasks.filter(t=>t.done).length,all=tasks.length;let list=tasks.filter(t=>taskFilter==='All'||(taskFilter==='Done'?t.done:!t.done));return `<div class="between"><div><h2>Your priorities</h2><p class="muted">${done} of ${all} completed</p></div>${addBtn('task','Task')}</div><div class="tabs">${['Open','Done','All'].map(f=>`<button class="pill ${taskFilter===f?'active':''}" data-taskfilter="${f}">${f}</button>`).join('')}</div><div class="glass"><div class="progress"><span style="width:${all?done/all*100:0}%"></span></div>${list.some(t=>!t.done&&t.due&&t.due<dayKey())?`<h3 class="overdue091">Overdue</h3>${taskRows(list.filter(t=>!t.done&&t.due&&t.due<dayKey()),true)}<h3 class="section">Other tasks</h3>`:''}${taskRows(list.filter(t=>t.done||!t.due||t.due>=dayKey()),true)}</div><section class="section glass">${head('target','Goals',`<button class="textbutton" data-new="goal">+ Add goal</button>`)}${plan.goals.length?plan.goals.map(g=>`<div class="taskrow ${g.done?'done':''}"><input type="checkbox" data-goal="${esc(g.id)}" ${g.done?'checked':''} aria-label="Complete goal"><span>${esc(g.title)}</span><button class="tiny" data-edit="goal:${esc(g.id)}" aria-label="Edit goal">${icon('edit')}</button></div>`).join(''):'<p class="empty">Set an intention for your week or month.</p>'}</section>`}
function focusView(){let today=plan.logs.filter(x=>dayKey(new Date(x.at))===dayKey()),minutes=today.reduce((s,x)=>s+x.minutes,0);return `<div class="dashgrid"><section class="glass">${head('timer','Deep work')}${focusCard()}<div class="tabs" style="justify-content:center">${[25,50,90].map(m=>`<button class="pill ${plan.focus.minutes===m?'active':''}" data-duration="${m}" ${plan.focus.end?'disabled':''}>${m} min</button>`).join('')}</div><label class="muted">Activity<select id="focusLabel" ${plan.focus.end?'disabled':''}>${['Study','Work','Reading','Chores','Exercise','Personal'].map(x=>`<option ${x===plan.focus.label?'selected':''}>${x}</option>`).join('')}</select></label></section><section class="glass">${head('target','Today')}<div class="big">${minutes} min</div><p class="muted">Completed focus time · ${today.length} sessions</p><div class="section">${addBtn('log','Log time manually')}</div></section></div><section class="section glass">${head('journal','Activity history')}${plan.logs.length?[...plan.logs].reverse().map(x=>`<div class="logrow"><div><strong>${esc(x.label)}</strong><div class="muted">${esc(pretty(dayKey(new Date(x.at))))}</div></div><div>${x.minutes} min <button class="tiny" data-edit="log:${esc(x.id)}" aria-label="Edit log">${icon('edit')}</button></div></div>`).join(''):'<p class="empty">Completed sessions will appear here.</p>'}</section>`}
function originalSettingsV3(){return `<section class="glass"><h2>Data & connectivity</h2><div class="setting"><h3>Offline-first storage</h3><p class="muted">Your calendar, tasks and preferences stay on this browser. Install from an HTTPS address (or localhost) and open once online for offline loading. An ordinary HTTP LAN address cannot cache the app on iPad.</p><div class="syncbuttons"><button class="secondary" data-data="export">Export backup</button><button class="secondary" data-data="import">Import backup</button><button class="secondary" data-data="ics">Export calendar (.ics)</button></div></div><div class="setting"><h3>iPhone & iPad</h3><p class="muted">Install the same free static app on both devices. Transfer the JSON backup using AirDrop or Files. Import replaces local data; back up both devices first. Automatic cross-device sync and live Apple Calendar access are not implemented.</p></div></section><section class="section">${settings()}</section>`}
const collections={event:'events',task:'tasks',goal:'goals',log:'logs'};
function openEditor(kind,id,occurrence){let arr=plan[collections[kind]],original=arr.find(x=>x.id===id)||{},item=original,series=!!(id&&['event','task'].includes(kind)&&original.repeat&&original.repeat!=='None');if(series&&occurrence&&!matchesRepeat090(kind==='event'?original.date:original.repeatStart||original.due||occurrence,occurrence,original.repeat,original.repeatUntil,original))occurrence=null;let title=kind==='log'?'Activity':kind[0].toUpperCase()+kind.slice(1);let fields=(series&&occurrence?`<label>Apply changes to<select name="scope091"><option value="series">Entire series</option><option value="one">Only ${esc(pretty(occurrence))}</option></select></label>`:'')+`<label>${kind==='log'?'Activity':'Title'}<input name="title" placeholder="Name" required maxlength="150" value="${esc(item.title||item.label||'')}"></label>`;if(kind==='event')fields+=`<label class="all-day091"><span>All-day event</span><input type="checkbox" name="allDay091" ${id&&!item.time?'checked':''}></label><label>Date<input type="date" name="date" required value="${esc(item.date||selectedDay)}"></label><label>Start time<input type="time" name="time" value="${esc(item.time||'')}"></label><label>End time (optional)<input type="time" name="end" value="${esc(item.end||'')}"></label><label>Notes<textarea name="notes" maxlength="1000">${esc(item.notes||'')}</textarea></label>`;if(kind==='event')fields+=`<label>Calendar color<select name="color">${['Blue','Purple','Green','Orange','Pink'].map(c=>`<option ${item.color===c?'selected':''}>${c}</option>`).join('')}</select></label>`;if(kind==='goal')fields+=`<label>Progress<input type="number" name="progress" min="0" max="100000000" step="any" required value="${Number(item.progress??(item.done?1:0))}"></label><label>Target<input type="number" name="target" min="0.01" max="100000000" step="any" required value="${Number(item.target||1)}"></label><label>Unit (optional)<input name="unit" maxlength="20" value="${esc(item.unit||'')}" placeholder="sessions, dollars, hours…"></label>`;if(kind==='task')fields+=`<label>Due date (optional)<input type="date" name="due" value="${esc(item.due||'')}"></label><label>Priority<select name="priority">${['High','Normal','Low'].map(x=>`<option ${x===(item.priority||'Normal')?'selected':''}>${x}</option>`).join('')}</select></label>`;if(kind==='event'||kind==='task')fields+=repeatFields090(item,kind);if(kind==='journal')fields+=`<label>Date<input type="date" name="date" required value="${esc(item.date||dayKey())}"></label><label>Reflection<textarea name="text" required maxlength="10000">${esc(item.text||'')}</textarea></label>`;if(kind==='log')fields+=`<label>Minutes<input type="number" name="minutes" min="1" max="1440" required value="${item.minutes||25}"></label>`;let el=$('#editor');el.innerHTML=`<h2>${id?'Edit':'New'} ${title.toLowerCase()}</h2><form id="itemForm" class="formgrid" data-kind="${kind}" data-id="${esc(id||'')}" data-occurrence091="${esc(occurrence||'')}">${fields}<div class="between">${id?`<button type="button" class="secondary" data-delete="${kind}:${esc(id)}">Delete</button>`:'<span></span>'}<div class="row"><button type="button" class="secondary" data-close>Cancel</button><button class="primary" type="submit">Save</button></div></div></form>`;el.showModal()}
function commitEditor(form){let f=Object.fromEntries(new FormData(form)),kind=form.dataset.kind,id=form.dataset.id||uid(),arr=plan[collections[kind]],old=arr.find(x=>x.id===id)||{};let item={...old,id,title:f.title.trim()};if(!item.title)return;if(kind==='event'){if(f.allDay091){f.time='';f.end=''}if(f.end&&(!f.time||f.end<=f.time)){toast('End time must be after start time.');return}Object.assign(item,{date:f.date,time:f.time,end:f.end,notes:f.notes,color:f.color})}if(kind==='task')Object.assign(item,{due:f.due,done:!!old.done,priority:f.priority||'Normal'});if(kind==='event'||kind==='task'){item.repeat=f.scope091==='one'?'None':f.repeat||'None';item.repeatUntil=item.repeat==='None'?'':f.repeatUntil||'';item.repeatInterval=Math.max(1,Math.min(365,Number(f.repeatInterval)||1));item.repeatDays=form.querySelectorAll('[name=repeatDays]:checked').length?Array.from(form.querySelectorAll('[name=repeatDays]:checked'),x=>Number(x.value)):[];if(item.repeat==='Weekly'&&!item.repeatDays.length){toast('Choose at least one weekday.');return}if(kind==='task')item.repeatStart=f.due||old.repeatStart||dayKey();if(item.repeatUntil&&item.repeatUntil<(kind==='event'?item.date:item.repeatStart)){toast('Repeat end must be after start.');return}if(kind==='event'&&f.blockTask)item.blockTask=f.blockTask;}if(kind==='goal'){item.target=Number(f.target);item.progress=Math.min(Number(f.progress),item.target);item.unit=f.unit.trim();item.done=item.progress>=item.target;}if(kind==='log')item={id,label:item.title,minutes:Number(f.minutes),at:old.at||Date.now()};if(f.scope091==='one'&&form.dataset.occurrence091&&old.id){let occurrence=form.dataset.occurrence091;old.skippedDays=[...new Set([...(old.skippedDays||[]),occurrence])];item={...item,id:uid(),repeat:'None',repeatUntil:'',repeatDays:[],repeatInterval:1,skippedDays:[]};if(kind==='task'){item.done=!!old.completedDays?.[occurrence];item.completedDays={};item.completedAt=item.done?(old.completedAt||null):null;if(old.completedDays){old.completedDays={...old.completedDays};delete old.completedDays[occurrence]}}arr.push(item)}else {let i=arr.findIndex(x=>x.id===id);if(i<0)arr.push(item);else arr[i]=item}if(kind==='event')selectedDay=item.date;savePlan();$('#editor').close();render();toast('Saved on this device')}
function downloadFile(name,text,type){let a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}
function exportBackup(){delete plan.journal;delete state.chat;delete state.memory;delete state.speak;downloadFile('HOME-backup-'+dayKey()+'.json',JSON.stringify({version:3,plan,state},null,2),'application/json')}
function importBackup(raw){let j=JSON.parse(raw);if(j.version!==3||!j.plan||!j.state)throw Error('Not a HOME v0.3 backup');for(let k of ['events','tasks','goals','logs'])if(!Array.isArray(j.plan[k])||j.plan[k].length>10000)throw Error('Invalid backup');for(let [k,arr] of Object.entries(j.plan)){if(k==='focus')continue;if(!Array.isArray(arr))continue;for(let x of arr)if(!x||typeof x.id!=='string'||(k==='logs'?typeof x.label!=='string':typeof x.title!=='string'))throw Error('Invalid items')}for(let x of j.plan.events)if(typeof x.date!=='string'||typeof x.time!=='string')throw Error('Invalid calendar');if(!Array.isArray(j.state.lights)||j.state.lights.length!==6)throw Error('Invalid settings');if(!confirm('Replace this device’s HOME data with the backup?'))return;plan={...freshPlan(),...j.plan};plan.focus={...freshPlan().focus,...j.plan.focus,end:0};state={...defaults,...j.state};savePlan();save();render();toast('Backup imported')}
function exportICS(){const clean=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,m=>'\\'+m);let now=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//HOME//Calendar//EN','CALSCALE:GREGORIAN'];for(let e of plan.events){let d=e.date.replace(/-/g,''),dt=t=>d+'T'+t.replace(':','')+'00';lines.push('BEGIN:VEVENT','UID:'+clean(e.id)+'@home.local','DTSTAMP:'+now,'SUMMARY:'+clean(e.title),e.time?'DTSTART:'+dt(e.time):'DTSTART;VALUE=DATE:'+d);if(e.end)lines.push('DTEND:'+dt(e.end));if(!e.time)lines.push('DTEND;VALUE=DATE:'+shift(e.date,1).replace(/-/g,''));if(e.notes)lines.push('DESCRIPTION:'+clean(e.notes));if(['Daily','Weekly','Monthly','Yearly'].includes(e.repeat))lines.push('RRULE:FREQ='+e.repeat.toUpperCase()+';INTERVAL='+(e.repeatInterval||1)+(e.repeat==='Weekly'&&e.repeatDays?.length?';BYDAY='+e.repeatDays.map(d=>['SU','MO','TU','WE','TH','FR','SA'][d]).join(','):'')+(e.repeatUntil?';UNTIL='+e.repeatUntil.replace(/-/g,'')+(e.time?'T235959':''):''));if(e.skippedDays?.length)lines.push((e.time?'EXDATE:':'EXDATE;VALUE=DATE:')+e.skippedDays.map(k=>k.replace(/-/g,'')+(e.time?'T'+e.time.replace(':','')+'00':'')).join(','));lines.push('END:VEVENT')}lines.push('END:VCALENDAR');downloadFile('HOME-calendar.ics',lines.join('\r\n')+'\r\n','text/calendar')}
function updateFocus(){let left=focusRemaining();let ring=$('#focusRing');if(ring&&!ambient&&!document.hidden)ring.style.setProperty('--progress',Math.max(0,Math.min(100,left/(plan.focus.minutes*60)*100))+'%');if(plan.focus.end&&left===0){plan.logs.push({id:uid(),label:plan.focus.label,minutes:plan.focus.minutes,at:Date.now()});plan.focus.end=0;plan.focus.remaining=plan.focus.minutes*60;savePlan();render();toast('Focus session complete');return}let el=$('#focusClock');if(el&&!ambient&&!document.hidden&&el.textContent!==countdown())el.textContent=countdown()}
setInterval(updateFocus,1000);document.addEventListener('visibilitychange',updateFocus);
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.new){if(d.new==='event'&&tab==='Today')selectedDay=dayKey();if(d.new==='event'&&tab==='Overview')selectedDay=shift(dayKey(),['Evening','Night'].includes(periodNow())?1:0);openEditor(d.new);}else if(d.edit){let [k,id]=d.edit.split(':');openEditor(k,id,d.occurrence091)}else if('close'in d)$('#editor').close();else if(d.delete){let [k,id]=d.delete.split(':');if(confirm('Delete this item?')){plan[collections[k]]=plan[collections[k]].filter(x=>x.id!==id);savePlan();$('#editor').close();render()}}else if(d.day){selectedDay=d.day;render()}else if(d.calmode){calMode=d.calmode;render()}else if(d.calnav){if(d.calnav==='today')selectedDay=dayKey();else if(calMode==='Month'){let x=asDate(selectedDay);x.setDate(1);x.setMonth(x.getMonth()+Number(d.calnav));selectedDay=dayKey(x)}else selectedDay=shift(selectedDay,Number(d.calnav)*(calMode==='Week'?7:1));render()}else if(d.taskfilter){taskFilter=d.taskfilter;render()}else if(d.roomgo){room=d.roomgo;navigate('Lighting')}else if(d.duration){plan.focus.minutes=Number(d.duration);plan.focus.remaining=plan.focus.minutes*60;plan.focus.end=0;savePlan();render()}else if(d.focus){if(d.focus==='start')plan.focus.end=Date.now()+(plan.focus.remaining||plan.focus.minutes*60)*1000;if(d.focus==='pause'){plan.focus.remaining=focusRemaining();plan.focus.end=0}if(d.focus==='reset'){plan.focus.end=0;plan.focus.remaining=plan.focus.minutes*60}savePlan();render()}else if(d.data==='export')exportBackup();else if(d.data==='import')$('#importFile').click();else if(d.data==='ics')exportICS()});
document.addEventListener('submit',e=>{if(e.target.id==='itemForm'){e.preventDefault();commitEditor(e.target)}});document.addEventListener('change',async e=>{let d=e.target.dataset;if(d.task||d.goal){let t=plan[d.task?'tasks':'goals'].find(x=>x.id===(d.task||d.goal));if(t){t.done=e.target.checked;if(d.task){t.completedAt=t.done?Date.now():null;if(t.repeat&&t.repeat!=='None'){t.completedDays={...(t.completedDays||{})};if(t.done)t.completedDays[dayKey()]=true;else delete t.completedDays[dayKey()];}}if(d.goal&&t.target)t.progress=t.done?t.target:0;}savePlan();if(d.task&&e.target.checked&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const row=e.target.closest('.taskrow');row?.classList.add('completing092');setTimeout(()=>{if(row?.isConnected)render()},220)}else render()}if(e.target.id==='focusLabel'){plan.focus.label=e.target.value;savePlan()}if(e.target.id==='importFile'){try{let f=e.target.files[0];if(f){if(f.size>5000000)throw Error('Backup too large');importBackup(await f.text())}}catch(err){toast('Could not import: '+err.message)}e.target.value=''}});

document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.tab)navigate(d.tab);else if(d.scene)choose(d.scene);else if(d.room){room=d.room;render()}else if(d.toggle){let l=state.lights.find(x=>x.id===d.toggle);l.on=!l.on;state.scene='Custom';save();render()}else if(d.action){switch(d.action){case'all':{let on=!state.lights.some(l=>l.on);state.lights.forEach(l=>l.on=on);state.scene='Custom';break}case'tv':state.tv=!state.tv;break;case'reset':if(confirm('Reset all local HOME data, including productivity items?')){state=JSON.parse(JSON.stringify(defaults));plan=freshPlan();savePlan()};break}save();render()}});
document.addEventListener('input',e=>{let d=e.target.dataset;if(d.bright){let l=state.lights.find(x=>x.id===d.bright),v=Number(e.target.value);l.b=v||l.b;l.on=v>0;state.scene='Custom';$('#b-'+l.id).textContent=v+'%';save()}if(d.temp){let l=state.lights.find(x=>x.id===d.temp);l.k=Number(e.target.value);state.scene='Custom';$('#k-'+l.id).textContent=l.k+'K';save()}if('volume'in d){state.volume=Number(e.target.value);$('#vol').textContent=state.volume+'%';save()}});document.addEventListener('change',e=>{if(e.target.matches('[data-bright],[data-temp]'))render()});/*START_V04*/if('serviceWorker'in navigator&&window.isSecureContext)navigator.serviceWorker.register('sw.js',{updateViaCache:'none'}).catch(()=>{});
