const readLocal=(k,f)=>{try{return JSON.parse(localStorage.getItem(k)||'null')??f}catch{return f}};
const writeLocal=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{}};
const displayDefaults={mode:'Auto',morning:'06:00',day:'10:00',evening:'17:00',night:'22:00',idle:0.5,city:null};
let display={...displayDefaults,...readLocal('home-display-v4',{})},nightDismissed='',lastPeriod='',lastDay=dayKey(),lastActivity=Date.now(),ambient=false,weather=readLocal('home-weather-v4',null),weatherError='',weatherBusy=false,cityResults=[];
function periodNow(){if(display.mode!=='Auto')return display.mode;let n=new Date(),t=n.getHours()*60+n.getMinutes(),pairs=[['Morning',display.morning],['Daytime',display.day],['Evening',display.evening],['Night',display.night]];let result='Night';for(let [name,v] of pairs){let [h,m]=v.split(':').map(Number);if(t>=h*60+m)result=name}return result}
function setDisplay(){writeLocal('home-display-v4',display);nightDismissed='';lastPeriod='';renderAdaptive(true)}
function displayConfig(){return `<section class="glass section"><h2>Display & atmosphere</h2><p class="note">Automatic layout follows your device clock. It never changes physical lights or interrupts an editor.</p><form id="displayForm" class="formgrid"><label>Dashboard<select name="mode">${['Auto','Morning','Daytime','Evening','Night'].map(x=>`<option ${display.mode===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="grid two">${[['morning','Morning starts'],['day','Daytime starts'],['evening','Evening starts'],['night','Night starts']].map(([k,n])=>`<label>${n}<input type="time" name="${k}" required value="${esc(display[k])}"></label>`).join('')}</div><label>Ambient display after inactivity<select name="idle">${[0,0.5,1,3,5,10,15,30].map(n=>`<option value="${n}" ${display.idle===n?'selected':''}>${n===0.5?'30 seconds':n?n+' minutes':'Never'}</option>`).join('')}</select></label><button class="primary" type="submit">Save display settings</button></form></section>`}
function weatherConfig(){return `<section class="glass section"><h2>Weather location</h2><p class="note">${display.city?'Selected: '+esc(display.city.label):'Choose a city to enable live weather.'} Location is not requested automatically. City queries and coordinates are sent to Open-Meteo.</p><form id="cityForm" class="row"><input name="city" placeholder="Search city (e.g. Tucson)" required minlength="2" maxlength="80" aria-label="City name"><button class="secondary">Search</button></form><div id="cityResults" class="cityresults"></div><p class="note">Forecast data: <a href="https://open-meteo.com/" target="_blank" rel="noopener" class="musiclink">Open-Meteo</a> · free for personal, non-commercial use.</p></section>`}
function settingsV3(){return `<section class="glass section"><h2>Clock faces</h2><p class="note">Swipe to change faces. Touch and hold to customize. Tap to return.</p><button class="secondary" data-ambient>Open full-screen clock</button></section>`+displayConfig()+weatherConfig()+syncSettings()+`<section class="glass section"><h2>Data & connectivity</h2><p class="note">Install from HTTPS for offline app loading. Back up regularly; browser storage can be cleared. Apple Calendar and Reminders are not connected.</p><div class="syncbuttons"><button class="secondary" data-data="export">Export backup</button><button class="secondary" data-data="import">Import backup</button><button class="secondary" data-data="ics">Export calendar (.ics)</button></div></section><section class="section">${settings()}</section>`}
